/* Siberia GSHHG sampled shoreline: 160 x 88, 55°-180°E, 47°-79°N.
   Each centre-sampled land hex is classified using 19 subhex land samples.
   Mixed cells contain 20-80% land; they remain passable coastal hexes.
   Serialized MSB-first and shared by gameplay/auditor; no network requests. */
(function(root){
  'use strict';
  const cols=160,rows=88,bounds={west:55,east:180,north:79,south:47};
  const bits='';
  const mixed='';
  const geo={cols,rows,bounds,bits,mixed,
    point(c,r){return {lon:bounds.west+(c+.5*(r&1)+.5)*(bounds.east-bounds.west)/cols,
      lat:bounds.north-(r+.5)*(bounds.north-bounds.south)/rows};}};
  root.SIBERIA_GEOGRAPHY=geo;
  if(typeof module!=='undefined')module.exports=geo;
})(typeof window!=='undefined'?window:globalThis);
